namespace {
void* LoadGLFunc(const char* name) {
    void* p = (void*)wglGetProcAddress(name);
    if (p == nullptr || p == (void*)0x1 || p == (void*)0x2 || p == (void*)0x3 || p == (void*)-1) {
        HMODULE mod = LoadLibraryA("opengl32.dll");
        p = (void*)GetProcAddress(mod, name);
    }
    return p;
}
}

